// Iteramos sobre todos los items que entran al nodo
return items.map(item => {
  const rawData = item.json;
  // Limpieza inicial de caracteres no numéricos (excepto el +)
  const rawPhone = rawData.telefono ? String(rawData.telefono).replace(/[^\d+,\/]/g, '') : "";

  if (!rawPhone) {
    return { 
      json: { ...rawData, telefonos_limpios: [], telefono_principal: "", telefono_fijo: "" } 
    };
  }

  const parts = rawPhone.split(/[\/\,]/);
  let finalNumbers = [];

  parts.forEach(num => {
    let cleaned = num.trim();

    // --- REGLA 4: PASAPORTE UNIVERSAL (Status Quo Internacional) ---
    // Si ya empieza con '+', lo aceptamos tal cual (sea +1, +593, +54, etc.)
    if (cleaned.startsWith('+')) {
      finalNumbers.push(cleaned);
      return;
    }

    // --- REGLA 6: CÓDIGOS INTERNACIONALES SIN '+' (Ej: Uruguay 598, Ecuador 593) ---
    // Si empieza con 5 y es largo (11+ dígitos), asumimos que es internacional sin el '+'
    if (cleaned.startsWith('5') && cleaned.length >= 11) {
      finalNumbers.push('+' + cleaned);
      return;
    }

    // --- REGLA 3: ARGENTINA - CÓDIGO 1115 ---
    if (cleaned.startsWith('1115')) {
      const base = '11' + cleaned.substring(4);
      finalNumbers.push('+549' + base);
      finalNumbers.push('+54' + base);
      return;
    }

    if (cleaned.startsWith('011')) {
      const base = cleaned.substring(1);
      finalNumbers.push('+549' + base);
      finalNumbers.push('+54' + base);
      return;
    }

    // --- REGLA 7: ARGENTINA - PREFIJO 15 ---
    if (cleaned.startsWith('15')) {
      const base = '11' + cleaned.substring(2);
      finalNumbers.push('+549' + base);
      return;
    }

    // --- REGLA 1: ARGENTINA - CAPITAL (11 + 8 dígitos) ---
    if (cleaned.startsWith('11') && cleaned.length === 10) {
      finalNumbers.push('+549' + cleaned);
      finalNumbers.push('+54' + cleaned);
      return;
    }

    // --- REGLA 5: ARGENTINA - INTERIOR (2, 3, 7 u 8) ---
    // Si tiene 10 dígitos y empieza con estos números, es probable que sea AR
    if (/^[2378]/.test(cleaned) && cleaned.length === 10) {
      finalNumbers.push('+549' + cleaned); // Móvil interior
      finalNumbers.push('+54' + cleaned);  // Fijo interior
      return;
    }

    // --- CASO POR DEFECTO: ANÁLISIS DE PROBABILIDAD ---
    if (!cleaned.startsWith('+')) {
      if (cleaned.startsWith('54')) {
        // Si empieza con 54 pero no tiene +, se lo ponemos
        finalNumbers.push('+' + cleaned);
      } else if (cleaned.length === 10) {
        // Si tiene 10 dígitos exactos pero no encajó en las reglas anteriores,
        // sigue habiendo alta probabilidad de que sea Argentina.
        finalNumbers.push('+549' + cleaned);
        finalNumbers.push('+54' + cleaned);
      } else {
        // Si es un número de longitud extraña, lo dejamos como está pero con el + preventivo
        finalNumbers.push('+' + cleaned);
      }
    }
  });

  // Limpiamos duplicados y valores vacíos
  const uniqueNumbers = [...new Set(finalNumbers)].filter(n => n.length > 5);

  return {
    json: {
      ...rawData,
      telefonos_limpios: uniqueNumbers,
      telefono_principal: uniqueNumbers[0] || "",
      telefono_fijo: uniqueNumbers[1] || "" 
    }
  };
});

// 1. CONFIGURACIÓN Y MAPEOS
const idToProf = {
  "1": ["AUSENTES", "AUSENTE"], 
  "2": ["CANCELADOS", "CANCELADO"], 
  "3": ["CONTROLES", "CONTROL"],
  "5": ["REVISACIONES", "REVISACION"], 
  "7": ["PLASMA", "PRP"], 
  "10": ["MESOTERAPIA", "MESO"], 
  "13": ["DERMO", "DERMOPIGMENTACION"]
};

// 🔥 Mapeo base de asistidos
const estadosRealizado = ["REALIZADO", "ATENDIDO"]; 

const calendarConfig = [
  { skyiaId: 10, node: "Get Events GHL meso", calId: "LzQBDcqDSopp37434OTm" },
  { skyiaId: 7, node: "Get Events GHL prp", calId: "Nn2PyACs0OBYSrQ5bFzu" },
  { skyiaId: 5,  node: "Get Events GHL revisaciones", calId: "fGnEFWqMyFh0VIPV1biz" },
  { skyiaId: 3,  node: "Get Events GHL controles", calId: "MEpJfFMuZXbtMgK8DbCy" },
  { skyiaId: 13,  node: "Get Events GHL dermo", calId: "wWpl7nHjIzE2wbndE8pE" }
];

const OFFSET = "-03:00";
const diasA_Escanear = 30;

const OFFSET_ARG = -3;
const hoy = new Date(new Date().getTime() + (OFFSET_ARG + 3) * 3600000);

// 2. RECOPILACIÓN DE DATOS
const skyiaFree = $("Get Free Slots CRM Capilea").all();
const skyiaDetails = $("Get_Skyia_Events_Details").all()
  .map(i => i.json)
  .filter(e => e.idTurno && e.estado !== "ELIMINADO");

const ghlDataByNode = {};

calendarConfig.forEach(conf => {
  try {
    const items = $(conf.node).all();
    let events = [];
    items.forEach(item => {
      if (item.json.events && Array.isArray(item.json.events)) events = events.concat(item.json.events);
      else if (item.json.startTime) events.push(item.json);
    });
    ghlDataByNode[conf.node] = events;
  } catch (e) { ghlDataByNode[conf.node] = []; }
});

const finalActions = [];

// 3. PROCESAMIENTO POR DÍA
for (let i = 0; i < diasA_Escanear; i++) {
  const fechaEvaluar = new Date(hoy);
  fechaEvaluar.setDate(hoy.getDate() + i);
  const fechaISO = `${fechaEvaluar.getFullYear()}-${String(fechaEvaluar.getMonth() + 1).padStart(2, '0')}-${String(fechaEvaluar.getDate()).padStart(2, '0')}`;

  const slotsSkyiaLibres = skyiaFree.filter(item => item.json.fecha && item.json.fecha.startsWith(fechaISO));

  calendarConfig.forEach(conf => {
    const currentSkyiaId = conf.skyiaId;
    const validProfNames = idToProf[currentSkyiaId] || [];

    const misSlotsLibres = slotsSkyiaLibres.filter(sf => Number(sf.json.idEntidad) === Number(currentSkyiaId));

    const skyiaRealAppointments = skyiaDetails.filter(sd => 
      validProfNames.includes(sd.profesional) && sd.fecha.startsWith(fechaISO)
    );

    let profTimes = misSlotsLibres.map(sf => sf.json.horaInicio.substring(0, 5))
      .concat(skyiaRealAppointments.map(sd => sd.horaInicio));

    let profGrid = [];
    if (profTimes.length > 0) {
      profTimes.sort();
      const minTime = profTimes[0];
      const maxTime = profTimes[profTimes.length - 1];

      let current = minTime;
      while (current <= maxTime) {
        profGrid.push(current);
        let [h, m] = current.split(':').map(Number);
        m += 15;
        if (m >= 60) { h += 1; m -= 60; }
        current = `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
      }
    }

    const ghlEvents = ghlDataByNode[conf.node].filter(e => e.startTime.startsWith(fechaISO) && e.calendarId === conf.calId);

    // --- LIMPIEZA Y ACTUALIZACIÓN DE GHL ---
    ghlEvents.forEach(ghlEv => {
      const horaGHL = ghlEv.startTime.split('T')[1].substring(0, 5);
      const esBloqueoGHL = ghlEv.title.toUpperCase().includes("OCUPADO SKYIA");
      const ahoraEstaLibreEnSkyia = misSlotsLibres.some(sf => sf.json.horaInicio.substring(0, 5) === horaGHL);

      if (esBloqueoGHL) {
        const estaEnGrilla = profGrid.includes(horaGHL);
        if (ahoraEstaLibreEnSkyia || !estaEnGrilla) {
          finalActions.push({ json: { action: "delete", appointmentId: ghlEv.id, title: ghlEv.title, reason: "Limpieza de Bloqueo Inválido/Fantasma" } });
        }
        return;
      }

      let pacienteEnSkyiaGlobal = skyiaDetails.find(sd => sd.fecha.startsWith(fechaISO) && sd.horaInicio === horaGHL && ghlEv.title.toUpperCase().includes(sd.paciente.toUpperCase()) && validProfNames.includes(sd.profesional));

      if (!pacienteEnSkyiaGlobal) {
        pacienteEnSkyiaGlobal = skyiaDetails.find(sd => sd.fecha.startsWith(fechaISO) && sd.horaInicio === horaGHL && ghlEv.title.toUpperCase().includes(sd.paciente.toUpperCase()));
      }

      if (pacienteEnSkyiaGlobal) {
        const profUpper = pacienteEnSkyiaGlobal.profesional ? pacienteEnSkyiaGlobal.profesional.toUpperCase() : "";
        // 🔥 Aislamos el estado con trim() para evitar fallos por espacios en blanco accidentales
        const estadoUpper = pacienteEnSkyiaGlobal.estado ? pacienteEnSkyiaGlobal.estado.toUpperCase().trim() : "";

        // Evaluamos Ausentes y Cancelados basándonos en 'profesional'
        if (idToProf["2"] && idToProf["2"].includes(profUpper)) {
          if (ghlEv.appointmentStatus !== "cancelled") finalActions.push({ json: { action: "updateStatus", appointmentId: ghlEv.id, status: "cancelled", title: ghlEv.title } });
          return; 
        }

        if (idToProf["1"] && idToProf["1"].includes(profUpper)) {
          if (ghlEv.appointmentStatus !== "noshow") finalActions.push({ json: { action: "updateStatus", appointmentId: ghlEv.id, status: "noshow", title: ghlEv.title } });
          return;
        }

        // 🔥 NUEVO: Lógica de Doctores y Asistidos
        const esDoctor = estadoUpper.startsWith("-");
        const esRealizado = estadosRealizado.includes(estadoUpper) || esDoctor;

        if (esRealizado) {
          // 'showed' es el status para GHL
          if (ghlEv.appointmentStatus !== "showed") {
            finalActions.push({ 
                json: { 
                    action: "updateStatus", 
                    appointmentId: ghlEv.id, 
                    status: "showed", 
                    title: ghlEv.title,
                    // Dato opcional en el log por si deseas auditar quién lo atendió
                    doctorAsignado: esDoctor ? pacienteEnSkyiaGlobal.estado.trim() : "N/A" 
                } 
            });
          }
          return;
        }

        if (validProfNames.includes(pacienteEnSkyiaGlobal.profesional)) return;
      }

      if (ahoraEstaLibreEnSkyia) {
        finalActions.push({ json: { action: "delete", appointmentId: ghlEv.id, title: ghlEv.title, reason: "Slot liberado/reagendado" } });
        return;
      }

      if (!pacienteEnSkyiaGlobal) {
        finalActions.push({ json: { action: "delete", appointmentId: ghlEv.id, title: ghlEv.title, reason: "No encontrado en Skyia" } });
      }
    });

    // --- NUEVOS AGENDAMIENTOS ---
    skyiaRealAppointments.forEach(sd => {
      const startTimeStr = `${fechaISO}T${sd.horaInicio}:00${OFFSET}`;
      const exists = ghlEvents.some(ge => ge.startTime === startTimeStr && ge.title.toUpperCase().includes(sd.paciente.toUpperCase()));

      if (!exists) {
        finalActions.push({
          json: {
            action: "create", calendarId: conf.calId, startTime: startTimeStr,
            endTime: `${fechaISO}T${sd.horaFin}:00${OFFSET}`, title: `${sd.paciente} - ${sd.producto}`,
            nombreCompleto: sd.paciente, producto: sd.producto, email: sd.mail || `sync_${sd.idPaciente}@skyia.com`, telefono: sd.telefono || "", idTurno: sd.idTurno
          }
        });
      }
    });

    // --- DETECCIÓN DE BLOQUEOS MANUALES (Ocupado Skyia) ---
    profGrid.forEach(horaGrid => {
      const estaLibre = misSlotsLibres.some(sf => sf.json.horaInicio.substring(0, 5) === horaGrid);
      const tieneCita = skyiaRealAppointments.some(sd => horaGrid >= sd.horaInicio && horaGrid < sd.horaFin);

      if (!estaLibre && !tieneCita) {
        const startTimeStr = `${fechaISO}T${horaGrid}:00${OFFSET}`;
        let [h, m] = horaGrid.split(':').map(Number);
        m += 15;
        if (m >= 60) { h += 1; m -= 60; }
        const horaFinStr = `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;

        const exists = ghlEvents.some(ge => ge.startTime === startTimeStr && ge.title.toUpperCase().includes("OCUPADO SKYIA"));

        if (!exists) {
          finalActions.push({
            json: {
              action: "create", calendarId: conf.calId, startTime: startTimeStr,
              endTime: `${fechaISO}T${horaFinStr}:00${OFFSET}`, title: "Ocupado Skyia",
              nombreCompleto: "Bloqueo Skyia", email: "sync@skyia.local", telefono: "", idTurno: `block_${currentSkyiaId}_${horaGrid.replace(':','')}`
            }
          });
        }
      }
    });
  });
}

if (finalActions.length === 0) {
  return [{ json: { action: "ninguna", status: "Sincronización Perfecta" } }];
}
return finalActions;

// Iteramos sobre TODOS los items que ingresan al nodo
return $input.all().map(item => {
    const itemData = item.json;
    let finalContactId = "";

    // 1. Caso de Éxito: Se creó normalmente
    if (itemData.contact && itemData.contact.id) {
        finalContactId = itemData.contact.id;
    } 
    // 2. Caso de Fallo: Extracción Segura
    else {
        let errorText = "";

        // Recopilamos el texto del error de las 3 posibles ubicaciones seguras
        if (itemData.error && typeof itemData.error.message === 'string') {
            errorText += itemData.error.message;
        }
        if (itemData.response && itemData.response.data) {
            errorText += JSON.stringify(itemData.response.data);
        }
        if (itemData.message && typeof itemData.message === 'string') {
            errorText += itemData.message;
        }

        // El Regex Cazador (Case insensitive y a prueba de caracteres de escape)
        const regex = /contactid["\\:\s]+([a-zA-Z0-9\-_]{15,30})/i;
        const match = errorText.match(regex);

        if (match && match[1]) {
            finalContactId = match[1];
        }
    }

    // Retornamos el item original junto con el ID resuelto para ESTE item en particular
    return {
        json: {
            ...itemData,
            resolvedContactId: finalContactId,
            _debugErrorText: finalContactId ? undefined : "No se encontró ID en el error" 
        }
    };
});

// 1. Obtenemos la fecha actual (momento de ejecución)
const ahora = new Date();

// Función auxiliar para formatear a DD/MM/YYYY
const formatFecha = (date) => {
  const day = String(date.getDate() ).padStart(2, '0');
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const year = date.getFullYear();
  return `${day}/${month}/${year}`;
};

// 2. Definimos fechaDesde (Hoy)
const fechaDesdeObj = new Date();
fechaDesdeObj.setDate(ahora.getDate() );
const fechaDesde = formatFecha(fechaDesdeObj);

// 3. Calculamos fechaHasta (Hoy + 7 días)
const fechaHastaObj = new Date();
fechaHastaObj.setDate(ahora.getDate() + 30);
const fechaHasta = formatFecha(fechaHastaObj);

// 4. Construimos la URL para consultar los huecos libres en ese rango
const baseUrl = "https://api.cloud.skyia.ar/skyia_api";

// Parámetros de configuración (Ajusta idAgenda o idSucursal si es necesario)
const queryParams = {
  api: "getAgendaTurnosLibres",
  x: "REEMPLAZAR_SKYIA_API_KEY",
  idAgenda: "2",
  tipoAgenda: "OTROS",
  idSucursal: "1",
  duracion: "15",
  //horaInicioAgenda: "10:00",
  //horaFinAgenda: "20:00",
  fechaDesde: fechaDesde,
  fechaHasta: fechaHasta
};

// Unimos todo en un string de URL
const finalUrl = `${baseUrl}?${Object.keys(queryParams).map(key => `${key}=${queryParams[key]}`).join('&')}`;

return [{
  json: {
    rangoConsulta: {
      inicio: fechaDesde,
      fin: fechaHasta
    },
    urlConsultaSkyia: finalUrl
  }
}];

const ahora = new Date();
ahora.setHours(0, 0, 0, 0);

const fechaFin = new Date();
fechaFin.setDate(ahora.getDate() + 30);
fechaFin.setHours(23, 59, 59, 999);

//QUITAR LUEGO
const fechaInicio = new Date();
fechaInicio.setDate(ahora.getDate());
fechaInicio.setHours(23, 59, 59, 999);

// Formato Skyia
const formatSkyia = (date) => {
  const d = String(date.getDate()).padStart(2, '0');
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const y = date.getFullYear();
  return `${d}/${m}/${y}`;
};

return [{
  json: {
    skyia: {
      desde: formatSkyia(fechaInicio),
      hasta: formatSkyia(fechaFin)
    },
    ghl: {
      startTime: fechaInicio.getTime(), // Milisegundos
      endTime: fechaFin.getTime()   // Milisegundos
    }
  }
}];
